        org.joda.time.format.PeriodFormatterBuilder.FieldFormatter formatter = createMockFormatter();
        // 123456ms = 123 seconds and 456 millis
        setFieldValue(formatter, 123456L);
        setFieldType(formatter, SECONDS_MILLIS);
        setMinDigits(formatter, 1);

        // valueLong = 123456. Digit count = 6. sum = max(6, 1) = 6.
