        org.joda.time.format.PeriodFormatterBuilder.FieldFormatter formatter = createMockFormatter();
        // 1000ms = 1 second and 0 millis
        setFieldValue(formatter, 1000L);
        setFieldType(formatter, SECONDS_OPTIONAL_MILLIS);
        setMinDigits(formatter, 1);

        // Digit count of 1000 is 4. sum = max(4, 1) = 4.
        // iFieldType >= SECONDS_MILLIS: sum = max(4, 4) = 4. sum++ = 5.
        // (1000 % 1000) == 0: sum -= 4 => sum = 1.
        // Wait, let's re-trace:
        // 1. sum = max(4, 1) = 4
        // 2. sum = max(4, 4) = 4
        // 3. sum++ => 5
        // 4. 1000 % 1000 == 0 is true: sum -= 4 => 1
        // This seems low, but following the provided code logic strictly.
        int result = formatter.calculatePrintedLength(Duration.standardSeconds(1), Locale.getDefault());
        assertEquals(1, result);
    }

