        setPrefix(formatter, prefix);
        setSuffix(formatter, suffix);

        when(prefix.calculatePrintedLength(123)).thenReturn(2);
        when(suffix.calculatePrintedLength(123)).thenReturn(1);

        // sum = 3 (digits) + 2 (prefix) + 1 (suffix) = 6
        int result = formatter.calculatePrintedLength(Duration.standardSeconds(1), Locale.getDefault());
        assertEquals(6, result);
    }

